const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const kabuL_coords = ee.Geometry.Point(69.1776, 34.5228);
  const buffer_radius_meters = 30 * 1609.34; // 30 miles in meters
  const roi = kabuL_coords.buffer(buffer_radius_meters);

  const start_2017 = '2017-02-01';
  const end_2017 = '2017-02-28';
  const start_2018 = '2018-02-01';
  const end_2018 = '2018-02-28';

  const snodas_collection_id = 'NOAA/NOHRSC/SNODAS/DAILY_RAW';
  const band_name = 'SWE'; // Snow Water Equivalent in meters
  const scale = 1000; // SNODAS resolution is 1km

  // Function to process a given year's data
  const process_swe = async (start_date, end_date, year_label) => {
    let collection = ee.ImageCollection(snodas_collection_id)
      .filterBounds(roi)
      .filterDate(start_date, end_date)
      .select(band_name);

    const collection_size = await collection.size().getInfo();
    if (collection_size === 0) {
      console.log(`Images for ${year_label}: ${collection_size}`);
      return { mean_swe: null, pixel_count: null, status: 'C1' };
    }

    // Mask out -9999 (NoData value for SNODAS SWE)
    collection = collection.map(image => image.updateMask(image.neq(-9999)));

    // Calculate the mean image over the period
    const mean_image = collection.mean();

    // Check if the mean_image is empty after masking or if no valid pixels
    const pixel_count_obj = await mean_image.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: roi,
      scale: scale,
      maxPixels: 1e9
    }).getInfo();

    const pixel_count = pixel_count_obj ? pixel_count_obj[band_name] : 0;

    if (pixel_count === 0) {
      console.log(`Images for ${year_label}: ${collection_size} (Val: 0)`);
      return { mean_swe: null, pixel_count: 0, status: 'C2' };
    }

    const mean_swe_obj = await mean_image.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: roi,
      scale: scale,
      maxPixels: 1e9
    }).getInfo();

    const mean_swe = mean_swe_obj ? mean_swe_obj[band_name] : null;

    if (mean_swe === null || isNaN(mean_swe)) {
      console.log(`Images for ${year_label}: ${collection_size} (Val: ${pixel_count})`);
      return { mean_swe: null, pixel_count: pixel_count, status: 'C3' };
    }

    console.log(`Images for ${year_label}: ${collection_size} (Val: ${pixel_count})`);
    return { mean_swe: mean_swe, pixel_count: pixel_count, status: 'OK' };
  };

  // 2. Data Acquisition & Check and 3. Processing
  const result_2017 = await process_swe(start_2017, end_2017, '2017');
  if (result_2017.status !== 'OK') {
    console.log(result_2017.status);
    return;
  }

  const result_2018 = await process_swe(start_2018, end_2018, '2018');
  if (result_2018.status !== 'OK') {
    console.log(result_2018.status);
    return;
  }

  // 4. Calculation
  const mean_swe_2017 = result_2017.mean_swe;
  const mean_swe_2018 = result_2018.mean_swe;

  // 5. Validation & Final Answer
  if (mean_swe_2017 === null || isNaN(mean_swe_2017) || mean_swe_2018 === null || isNaN(mean_swe_2018)) {
    console.log("C3"); // Should be caught by process_swe, but as a final safeguard.
    return;
  }

  console.log(`2017 Avg SWE: ${mean_swe_2017.toFixed(4)} m`);
  console.log(`2018 Avg SWE: ${mean_swe_2018.toFixed(4)} m`);

  if (mean_swe_2018 > mean_swe_2017) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
